<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Notification\Message\Domain\ValueObject\MessageTenantVO;
use Civi\Lughauth\Features\Notification\Message\Domain\ValueObject\Holder\MessageTenantAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the MessageTenantAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class MessageTenantAttributeHolderUnitTest extends TestCase
{
        /**
         * Asserts that the code attribute is not assigned by default
         * and that getTenant returns null on a freshly created holder.
         */
        public function testTenantNotAssignedByDefault(): void
        {
            // Arrange
            $holder = new ImplWithMessageTenantAttributeHolderUnitTest();

            // Assert
            $this->assertFalse($holder->isTenantAssigned());
            $this->assertNull($holder->getTenant());
        }
}
class ImplWithMessageTenantAttributeHolderUnitTest
{
  use MessageTenantAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedTenantRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultTenant();
    }}
